def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    threshold = 150
    count = sum(1 for value in values if value > threshold)
    return {
        "value": count,
        "trace": {
            "values": values,
            "threshold": threshold,
            "years_exceeding_threshold": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "years"
            }
        }
    }
